import json,pathlib
def merge(base_path,ours_path,theirs_path):
    def pairs(items):
        result={}
        for key,value in items:
            if key in result:raise ValueError('duplicate JSON key')
            result[key]=value
        return result
    def load(path):
        doc=json.loads(pathlib.Path(path).read_text(encoding='utf8'),object_pairs_hook=pairs)
        if not isinstance(doc,dict) or set(doc)!={'services'} or not isinstance(doc['services'],dict):raise ValueError('closed services schema')
        values=doc['services']
        if any(not name or type(port) is not int or not 1<=port<=65535 for name,port in values.items()) or len(set(values.values()))!=len(values):raise ValueError('invalid or duplicate service ports')
        return values
    try:base=load(base_path);ours=load(ours_path);theirs=load(theirs_path)
    except (OSError,ValueError,TypeError):return False
    absent=object();result={}
    for key in base.keys()|ours.keys()|theirs.keys():
        b,o,t=base.get(key,absent),ours.get(key,absent),theirs.get(key,absent)
        if o==t:value=o
        elif o==b:value=t
        elif t==b:value=o
        else:return False
        if value is not absent:result[key]=value
    if len(set(result.values()))!=len(result):return False
    pathlib.Path(ours_path).write_text(json.dumps({'services':result},ensure_ascii=False,sort_keys=True,indent=2)+'\n',encoding='utf8')
    return True
```

